import { fulfill } from "./service";
import { Inventory, Order } from "./model";
const inventory: Inventory = { available: 12, reserved: 0 };
const orders: Order[] = [
  { kind: "purchase", id: "A-1", quantity: 3, note: { text: "priority" } },
  { kind: "cancel", id: "A-2" }
];
export const outcomes = fulfill(orders, inventory);
export const firstLabel = outcomes[0]?.kind === "accepted" ? outcomes[0].label : "none";

export type Order =
  | { kind: "purchase"; id: string; quantity: number; note?: { text?: string } }
  | { kind: "cancel"; id: string };
export interface Inventory { available: number; reserved: number; }
export type Outcome =
  | { kind: "accepted"; id: string; quantity: number; label: string }
  | { kind: "rejected"; id: string; reason: string };
export function isPurchase(order: Order): order is Extract<Order, { kind: "purchase" }> {
  return order.kind === "purchase";
}

import { Inventory, Order, Outcome, isPurchase } from "./model";

export function fulfill(orders: readonly Order[], stock: Inventory): Outcome[] {
  const outcomes: Outcome[] = [];
  const { available, ...previous } = stock;
  let remaining = available;
  orders: for (const [index, order] of orders.entries()) {
    if (index > 100) break orders;
    if (isPurchase(order) && order.quantity <= 0) {
      outcomes.push({ kind: "rejected", id: order.id, reason: "Quantity must be positive" });
      continue orders;
    }
    switch (order.kind) {
      case "purchase": {
        const { id, quantity, note = {} } = order;
        const label = note.text?.trim() ?? `Order ${id}`;
        if (quantity > remaining) {
          outcomes.push({ kind: "rejected", id, reason: "Insufficient stock" });
          break;
        }
        try {
          remaining -= quantity;
          outcomes.push({ kind: "accepted", id, quantity, label });
        } catch (error) {
          const reason = error instanceof Error ? error.message : "Unknown error";
          outcomes.push({ kind: "rejected", id, reason });
        } finally {
          stock.reserved = previous.reserved + available - remaining;
        }
        break;
      }
      case "cancel":
        outcomes.push({ kind: "rejected", id: order.id, reason: "Cancelled" });
        break;
      default: {
        const exhaustive: never = order;
        return exhaustive;
      }
    }
  }
  const updated = { ...stock, available: remaining };
  stock.available = updated.available;
  return [...outcomes];
}

